mutants.find:
for (const run of group) {
  this.enqueue(run.runId, event);
  // Only the final attempt's evidence is reported, as under pytest.
  discardCaptured(run.runId);
}

mutants.replace:
for (const run of group) {
  this.enqueue(run.runId, event);
  // Only the final attempt's evidence is reported, as under pytest.
  if (run === lead) discardCaptured(run.runId);
}
